mapper.select:
WITH matched_data AS ( SELECT p.class_name, p.entity_id, p.entity_code, p.title, p.summary, p.updated_time, ts_rank(p.search_vector, q.query) AS score, q.query AS matched_query FROM platform_search_index p, websearch_to_tsquery('simple', #{keyword}) q(query) WHERE p.search_vector @@ q.query
AND p.class_name = #{className}
ORDER BY score DESC, p.updated_time DESC LIMIT #{pageSize} OFFSET #{offset} ) SELECT m.class_name AS className, m.entity_id AS entityId, m.entity_code AS entityCode, m.title AS title, m.summary AS summary, m.score AS score, m.updated_time AS updatedTime FROM matched_data m
